50: std::unique_ptr<Gdiplus::Bitmap> CreateBitmapFromIcon(
51:     HICON hIcon, std::vector<std::int32_t> &buffer) {
52:     ICONINFO iconInfo = {0};
53:     GetIconInfo(hIcon, std::addressof(iconInfo));
54: 
55:     BITMAP bm = {0};
56:     GetObject(iconInfo.hbmColor, sizeof(bm), std::addressof(bm));
57: 
58:     std::unique_ptr<Gdiplus::Bitmap> bitmap;
59: 
60:     if (bm.bmBitsPixel == 32) {
61:         auto hDC = GetDC(nullptr);
62: 
63:         BITMAPINFO bmi = {0};
64:         bmi.bmiHeader.biSize = sizeof(BITMAPINFOHEADER);
65:         bmi.bmiHeader.biWidth = bm.bmWidth;
66:         bmi.bmiHeader.biHeight = -bm.bmHeight;
67:         bmi.bmiHeader.biPlanes = 1;
68:         bmi.bmiHeader.biBitCount = 32;
69:         bmi.bmiHeader.biCompression = BI_RGB;
70: 
71:         auto nBits = bm.bmWidth * bm.bmHeight;
72:         buffer.resize(nBits);
73:         GetDIBits(hDC, iconInfo.hbmColor, 0, bm.bmHeight,
74:                   std::addressof(buffer[0]), std::addressof(bmi),
75:                   DIB_RGB_COLORS);
76: 
77:         auto hasAlpha = false;
78:         for (std::int32_t i = 0; i < nBits; i++) {
79:             if ((buffer[i] & 0xFF000000) != 0) {
80:                 hasAlpha = true;
81:                 break;
82:             }
83:         }
84: 
85:         if (!hasAlpha) {
86:             std::vector<std::int32_t> maskBits(nBits);
87:             GetDIBits(hDC, iconInfo.hbmMask, 0, bm.bmHeight,
88:                       std::addressof(maskBits[0]), std::addressof(bmi),
89:                       DIB_RGB_COLORS);
90: 
91:             for (std::int32_t i = 0; i < nBits; i++) {
92:                 if (maskBits[i] == 0) {
93:                     buffer[i] |= 0xFF000000;
94:                 }
95:             }
96:         }
97: 
98:         bitmap.reset(new Gdiplus::Bitmap(
99:             bm.bmWidth, bm.bmHeight, bm.bmWidth * sizeof(std::int32_t),
100:             PixelFormat32bppARGB,
101:             static_cast<BYTE *>(
102:                 static_cast<void *>(std::addressof(buffer[0])))));
103: 
104:         ReleaseDC(nullptr, hDC);
105:     } else {
106:         bitmap.reset(Gdiplus::Bitmap::FromHICON(hIcon));
107:     }
108: 
109:     DeleteObject(iconInfo.hbmColor);
110:     DeleteObject(iconInfo.hbmMask);
111: 
112:     return bitmap;
113: }
