145: std::vector<unsigned char> HIconToPNG(HICON hIcon) {
146:     GdiPlusInit init;
147: 
148:     std::vector<std::int32_t> buffer;
149:     auto bitmap = CreateBitmapFromIcon(hIcon, buffer);
150: 
151:     CLSID encoder;
152:     if (GetEncoderClsid(L"image/png", std::addressof(encoder)) == -1) {
153:         return std::vector<unsigned char>{};
154:     }
155: 
156:     IStream *tmp;
157:     if (CreateStreamOnHGlobal(nullptr, TRUE, std::addressof(tmp)) != S_OK) {
158:         return std::vector<unsigned char>{};
159:     }
160: 
161:     std::unique_ptr<IStream, IStreamDeleter> pStream{tmp};
162: 
163:     if (bitmap->Save(pStream.get(), std::addressof(encoder), nullptr) !=
164:         Gdiplus::Status::Ok) {
165:         return std::vector<unsigned char>{};
166:     }
167: 
168:     STATSTG stg = {0};
169:     LARGE_INTEGER offset = {0};
170: 
171:     if (pStream->Stat(std::addressof(stg), STATFLAG_NONAME) != S_OK ||
172:         pStream->Seek(offset, STREAM_SEEK_SET, nullptr) != S_OK) {
173:         return std::vector<unsigned char>{};
174:     }
175: 
176:     std::vector<unsigned char> result(
177:         static_cast<std::size_t>(stg.cbSize.QuadPart));
178:     ULONG ul;
179: 
180:     if (pStream->Read(std::addressof(result[0]),
181:                       static_cast<ULONG>(stg.cbSize.QuadPart),
182:                       std::addressof(ul)) != S_OK ||
183:         stg.cbSize.QuadPart != ul) {
184:         return std::vector<unsigned char>{};
185:     }
186: 
187:     return result;
188: }
