204: std::vector<unsigned char> GetIcon(const std::string &name, int size,
205:                                    UINT flag) {
206:     ComInit init;
207: 
208:     flag |= SHGFI_ICON;
209: 
210:     switch (size) {
211:         case 16:
212:             flag |= SHGFI_SMALLICON;
213:             break;
214:         case 32:
215:             flag |= SHGFI_LARGEICON;
216:             break;
217:         case 64:
218:         case 256:
219:             flag |= SHGFI_SYSICONINDEX;
220:             break;
221:     }
222: 
223:     SHFILEINFOW sfi = {0};
224:     auto hr = SHGetFileInfoW(Utf8ToWide(name).c_str(), 0, std::addressof(sfi),
225:                              sizeof(sfi), flag);
226:     HICON hIcon;
227: 
228:     if (FAILED(hr)) {
229:         return std::vector<unsigned char>{};
230:     }
231: 
232:     if (size == 16 || size == 32) {
233:         hIcon = sfi.hIcon;
234:     } else {
235:         HIMAGELIST *imageList;
236:         hr = SHGetImageList(
237:             size == 64 ? SHIL_EXTRALARGE : SHIL_JUMBO, IID_IImageList,
238:             static_cast<void **>(
239:                 static_cast<void *>(std::addressof(imageList))));
240: 
241:         if (FAILED(hr)) {
242:             return std::vector<unsigned char>{};
243:         }
244: 
245:         hr = static_cast<IImageList *>(static_cast<void *>(imageList))
246:                  ->GetIcon(sfi.iIcon, ILD_TRANSPARENT, std::addressof(hIcon));
247: 
248:         if (FAILED(hr)) {
249:             return std::vector<unsigned char>{};
250:         }
251:     }
252: 
253:     auto buffer = HIconToPNG(hIcon);
254:     DestroyIcon(hIcon);
255:     return buffer;
256: }
